def solve():
    results = []

    for m in range(1, 101):
        # 1. Check if K is an integer
        if (m * (m + 1)) % 6 != 0:
            continue

        K = (m * (m + 1)) // 6

        # We need to find two non-empty disjoint subsets X, Y summing to K.

        # DP state: achievable_sums maps (s_X, s_Y) -> set of (e_X, e_Y) statuses
        # e_X=1 if X is non-empty, e_Y=1 if Y is non-empty.
        # Initial state: sum (0, 0) is achievable with empty sets (0, 0).
        achievable_sums = {(0, 0): {(0, 0)}}

        # Iterate through elements i = 1 to m
        for i in range(1, m + 1):
            next_achievable_sums = achievable_sums.copy()

            # Iterate over all currently achievable states
            for (s_X, s_Y), statuses in achievable_sums.items():

                # Try adding i to X
                if s_X + i <= K:
                    new_s_X, new_s_Y = s_X + i, s_Y
                    # New status: X is definitely non-empty (1), Y status carries over (e_Y)
                    new_statuses = set()
                    for e_X, e_Y in statuses:
                        new_statuses.add((1, e_Y))

                    if (new_s_X, new_s_Y) not in next_achievable_sums:
                        next_achievable_sums[(new_s_X, new_s_Y)] = set()
                    next_achievable_sums[(new_s_X, new_s_Y)].update(new_statuses)

                # Try adding i to Y
                if s_Y + i <= K:
                    new_s_X, new_s_Y = s_X, s_Y + i
                    # New status: Y is definitely non-empty (1), X status carries over (e_X)
                    new_statuses = set()
                    for e_X, e_Y in statuses:
                        new_statuses.add((e_X, 1))

                    if (new_s_X, new_s_Y) not in next_achievable_sums:
                        next_achievable_sums[(new_s_X, new_s_Y)] = set()
                    next_achievable_sums[(new_s_X, new_s_Y)].update(new_statuses)

            achievable_sums = next_achievable_sums

        # Check the target state (K, K)
        if (K, K) in achievable_sums:
            # Check if the status (1, 1) is present for (K, K), meaning both X and Y are non-empty.
            if (1, 1) in achievable_sums[(K, K)]:
                results.append(m)

    return results

m_list = solve()
print(f"Values of m that satisfy the condition: {m_list}")

def count_valid_m(limit):
    count = 0
    for m in range(1, limit + 1):
        # Check if m*(m+1) is divisible by 6
        if (m * (m + 1)) % 6 == 0:
            count += 1
    return count

print(f"Count of m <= 100 where K = m(m+1)/6 is an integer: {count_valid_m(100)}")

